sksl:
uniform shader image;
uniform shader bright;
uniform float2 size;
uniform float time;
uniform float blur;
uniform float threshold;
uniform float intensity;
layout(color) uniform half4 color;
uniform float opacity;
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    half4 g = bright.eval(coord);
    float3 base = c.a > 0.0 ? float3(c.rgb) / float(c.a) : float3(0.0);
    float glow = clamp(float(g.r) * intensity * clamp(opacity, 0.0, 1.0) * 4.41, 0.0, 1.0);
    float3 add = glow * float3(color.rgb);
    float3 rgb = base + add - base * add;
    float a = max(float(c.a), glow);
    return half4(half3(clamp(rgb, 0.0, 1.0)) * half(a), half(a));
}
